{'role': 'user', 'content': [{'tool_use_id': 'toolu_01Paias7T6ymy83efbpTbMi8', 'type': 'tool_result', 'content': '     1→import { create } from "zustand";
     2→import type { BridgeStatus, DeviceInfo, PlayerInfo, BridgeState } from "../types";
     3→
     4→export type DotStatus = "connected" | "disconnected" | "degraded";
     5→
     6→interface BridgeStoreState {
     7→  // WebSocket connection state
     8→  wsConnected: boolean;
     9→
    10→  // Bridge state (from WebSocket bridge_status messages)
    11→  status: BridgeStatus;
    12→  port: number;
    13→  networkInterface: string | null;
    14→  jarExists: boolean;
    15→  jreAvailable: boolean;
    16→  restartCount: number;
    17→  routeCorrect: boolean | null;
    18→  routeWarning: string | null;
    19→  devices: Record<string, DeviceInfo>;
    20→  players: Record<string, PlayerInfo>;
    21→
    22→  // Pioneer liveness (from WebSocket pioneer_status messages)
    23→  isReceiving: boolean;
    24→  lastMessageAgeMs: number;
    25→
    26→  // Computed status for TopBar StatusDot
    27→  dotStatus: DotStatus;
    28→
    29→  // True while WS is not yet connected OR bridge is still launching.
    30→  // Clears once the WS has connected and the bridge reaches a stable state.
    31→  isStartingUp: boolean;
    32→
    33→  // Actions
    34→  setWsConnected: (connected: boolean) => void;
    35→  setBridgeState: (state: BridgeState) => void;
    36→  setPioneerStatus: (isReceiving: boolean, ageMs: number) => void;
    37→}
    38→
    39→function computeDotStatus(status: BridgeStatus): DotStatus {
    40→  if (status === "running") return "connected";
    41→  if (status === "fallback") return "degraded";
    42→  return "disconnected";
    43→}
    44→
    45→/** Startup is in progress until WS is open AND bridge has left "starting". */
    46→function computeIsStartingUp(wsConnected: boolean, status: BridgeStatus): boolean {
    47→  return !wsConnected || status === "starting";
    48→}
    49→
    50→export const useBridgeStore = create<BridgeStoreState>((set) => ({
    51→  wsConnected: false,
    52→  status: "stopped",
    53→  port: 0,
    54→  networkInterface: null,
    55→  jarExists: false,
    56→  jreAvailable: false,
    57→  restartCount: 0,
    58→  routeCorrect: null,
    59→  routeWarning: null,
    60→  devices: {},
    61→  players: {},
    62→  isReceiving: false,
    63→  lastMessageAgeMs: -1,
    64→  dotStatus: "disconnected",
    65→  isStartingUp: true,
    66→
    67→  setWsConnected: (connected: boolean) =>
    68→    set((prev) => ({
    69→      wsConnected: connected,
    70→      isStartingUp: computeIsStartingUp(connected, prev.status),
    71→    })),
    72→
    73→  setBridgeState: (state: BridgeState) =>
    74→    set((prev) => ({
    75→      status: state.status,
    76→      port: state.port,
    77→      networkInterface: state.network_interface,
    78→      jarExists: state.jar_exists,
    79→      jreAvailable: state.jre_available,
    80→      restartCount: state.restart_count,
    81→      routeCorrect: state.route_correct,
    82→      routeWarning: state.route_warning,
    83→      devices: state.devices,
    84→      players: state.players,
    85→      dotStatus: computeDotStatus(state.status),
    86→      isStartingUp: computeIsStartingUp(prev.wsConnected, state.status),
    87→    })),
    88→
    89→  setPioneerStatus: (isReceiving: boolean, ageMs: number) =>
    90→    set((prev) => ({
    91→      isReceiving,
    92→      lastMessageAgeMs: ageMs,
    93→      dotStatus: computeDotStatus(prev.status),
    94→    })),
    95→}));
    96→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01Tj71Fr7ZqgAmbRz6aigQg4', 'type': 'tool_result', 'content': '     1→/** WebSocket client — auto-reconnect, dispatches to Zustand stores.
     2→ *
     3→ * Per frontend/CLAUDE.md: Components never touch WS directly.
     4→ * This module manages the connection and routes typed messages to stores.
     5→ */
     6→
     7→import type { WSMessage } from "../types";
     8→import { useBridgeStore } from "../stores/bridgeStore";
     9→
    10→const WS_URL = `ws://${window.location.hostname}:8000/ws`;
    11→
    12→let ws: WebSocket | null = null;
    13→let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    14→let backoff = 1000; // ms, doubles on each failure up to 30s
    15→const MAX_BACKOFF = 30000;
    16→
    17→function dispatch(msg: WSMessage): void {
    18→  switch (msg.type) {
    19→    case "bridge_status":
    20→      useBridgeStore.getState().setBridgeState(msg.payload);
    21→      break;
    22→    case "pioneer_status":
    23→      useBridgeStore
    24→        .getState()
    25→        .setPioneerStatus(
    26→          msg.payload.is_receiving,
    27→          msg.payload.last_message_age_ms,
    28→        );
    29→      break;
    30→  }
    31→}
    32→
    33→function onOpen(): void {
    34→  backoff = 1000;
    35→  useBridgeStore.getState().setWsConnected(true);
    36→}
    37→
    38→function onMessage(event: MessageEvent): void {
    39→  try {
    40→    const msg = JSON.parse(event.data) as WSMessage;
    41→    dispatch(msg);
    42→  } catch {
    43→    // Ignore malformed messages
    44→  }
    45→}
    46→
    47→function onClose(): void {
    48→  ws = null;
    49→  useBridgeStore.getState().setWsConnected(false);
    50→  scheduleReconnect();
    51→}
    52→
    53→function onError(): void {
    54→  ws?.close();
    55→}
    56→
    57→function scheduleReconnect(): void {
    58→  if (reconnectTimer) return;
    59→  reconnectTimer = setTimeout(() => {
    60→    reconnectTimer = null;
    61→    connectWebSocket();
    62→  }, backoff);
    63→  backoff = Math.min(backoff * 2, MAX_BACKOFF);
    64→}
    65→
    66→export function connectWebSocket(): void {
    67→  if (ws) return;
    68→
    69→  try {
    70→    ws = new WebSocket(WS_URL);
    71→    ws.onopen = onOpen;
    72→    ws.onmessage = onMessage;
    73→    ws.onclose = onClose;
    74→    ws.onerror = onError;
    75→  } catch {
    76→    scheduleReconnect();
    77→  }
    78→}
    79→
    80→export function disconnectWebSocket(): void {
    81→  if (reconnectTimer) {
    82→    clearTimeout(reconnectTimer);
    83→    reconnectTimer = null;
    84→  }
    85→  if (ws) {
    86→    ws.onclose = null; // Prevent reconnect
    87→    ws.close();
    88→    ws = null;
    89→  }
    90→}
    91→'}]}

